"""Measure the artificial memorization of finetune.py: GSSCD (content) and OFS-k (motion) of videos generated by the
fine-tuned model. See section 10 of README.md.

Steps:
  python memorization_eval.py prompts     the memorized captions, and as many random background captions
  python main.py --model outputs/finetune/final batch ...     generate one video per caption
  python memorization_eval.py metrics     GSSCD and OFS-k of every video, and the averages
  python memorization_eval.py plot        figures of the results
  python memorization_eval.py compare     figures of the fine-tuned model against the original model (same prompts)

Mitigation methods on the fine-tuned model (the same captions, generated with --experiments guard,soften,clip,noise,sail):
  python memorization_eval.py metrics --experiments guard,soften,clip,noise,sail
  python memorization_eval.py plot --experiment guard          (and the other methods)
  python memorization_eval.py mitigation  figures of all the methods against no mitigation and the original model

Both metrics are from Chen et al., "Investigating Memorization in Video Diffusion Models". Every generated video is
compared with the exact clip it was fine-tuned on: the 16 frames of finetune.py's read_clip, center-cropped.
"""
import argparse
import math
import os
import re

import numpy as np
import pandas as pd
import torch
import torch.nn.functional as F
from torchvision.models.optical_flow import Raft_Large_Weights, raft_large
from tqdm import tqdm

from finetune import read_clip
from sscd import load_sscd
from webvid import embed, gif_frames, square, video_path

SSCD_SIZE = 288  # SSCD's evaluation size, as in `webvid.py gsscd`
FLOW_SIZE = 256  # the size of the fine-tuning; RAFT needs a multiple of 8


# ------------------------------------------------------------------------------------------------------------------
# Part 1: the captions to generate
# ------------------------------------------------------------------------------------------------------------------

def run_prompts(args):
    """Write the sheet for `main.py batch`: every memorized sample once, and the same number of random background
    samples. The index is the videoid, so each generated video is named after the training video it should match."""
    table = pd.read_csv(args.table, keep_default_na=False)
    memorized = table[table["role"] == "memorized"]
    background = table[table["role"] == "background"].sample(n=len(memorized), random_state=args.seed)
    sheet = pd.concat([memorized, background]).rename(columns={"videoid": "index"})
    sheet = sheet[["index", "caption", "role", "copies"]]
    assert sheet["index"].is_unique and sheet["caption"].is_unique  # the table of finetune.py guarantees this
    os.makedirs(args.out, exist_ok=True)
    out = os.path.join(args.out, "prompts.csv")
    sheet.to_csv(out, index=False)
    print(f"{len(memorized)} memorized + {len(background)} background captions -> {out}")


# ------------------------------------------------------------------------------------------------------------------
# Part 2: the metrics
# ------------------------------------------------------------------------------------------------------------------

@torch.no_grad()
def optical_flow(raft, frames):
    """RAFT flow between consecutive frames. frames: [n, 3, H, W] in [0, 1] -> flows [n - 1, 2, H, W] on the GPU.
    A generated video has one frame per 4 frames of its training video, and read_clip takes the same stride, so the
    flows of both videos cover the same amount of time."""
    x = frames.cuda() * 2 - 1  # RAFT takes [-1, 1]
    return torch.cat([raft(x[:-1][i:i + 8], x[1:][i:i + 8])[-1] for i in range(0, len(x) - 1, 8)])  # [-1]: final estimate


def flow_similarity(generated, training):
    """S (Eq. 3): S[i, j] is the cosine similarity of the flow vectors of generated flow i and training flow j, averaged
    over the pixels. generated: [a, 2, H, W], training: [b, 2, H, W] -> [a, b]."""
    g = F.normalize(generated, dim=1).flatten(1)  # unit vector at every pixel; a zero vector stays zero
    t = F.normalize(training, dim=1).flatten(1)
    pixels = generated.shape[2] * generated.shape[3]
    return g @ t.T / pixels


def natural_motion(flow, min_magnitude, min_entropy, bins=36):
    """The natural motion filter of the paper: which flows to ignore, [n] bool. Static: the mean flow length is small.
    Camera panning: nearly all the pixels move in the same direction, so the entropy of the histogram of the flow angles
    is low. The paper does not give the thresholds or the bins; the entropy here is divided by its largest value, so
    it goes from 0 (one direction) to 1 (all directions equally)."""
    magnitude = flow.norm(dim=1).flatten(1).mean(1)
    angle = torch.atan2(flow[:, 1], flow[:, 0]).flatten(1)  # in [-pi, pi]
    index = ((angle + math.pi) / (2 * math.pi) * bins).long().clamp(0, bins - 1)
    p = torch.stack([torch.bincount(row, minlength=bins) for row in index]).float()
    p = p / p.sum(1, keepdim=True)
    entropy = -(p * p.clamp_min(1e-12).log()).sum(1) / math.log(bins)
    return (magnitude < min_magnitude) | (entropy < min_entropy)


def ofs_k(S, k, ignored_generated=None, ignored_training=None):
    """OFS-k (Eq. 4): the best average of S over k consecutive flows of both videos, over all the alignments of the two
    windows. With the natural motion filter, a window that contains an ignored flow does not count (the paper does not
    say how the filter enters Eq. 4). NaN if no window is left."""
    a, b = S.shape
    ignored_generated = torch.zeros(a, dtype=torch.bool) if ignored_generated is None else ignored_generated.cpu()
    ignored_training = torch.zeros(b, dtype=torch.bool) if ignored_training is None else ignored_training.cpu()
    best = float("nan")
    for i in range(a - k + 1):
        if ignored_generated[i:i + k].any():
            continue
        for j in range(b - k + 1):
            if ignored_training[j:j + k].any():
                continue
            score = S[range(i, i + k), range(j, j + k)].mean().item()
            best = score if math.isnan(best) else max(best, score)
    return best


def summarize(df, by, ofs):
    """Mean, median and share of memorized videos of both metrics, per group."""
    return df.groupby(by).agg(
        videos=("videoid", "size"),
        gsscd_mean=("gsscd", "mean"), gsscd_median=("gsscd", "median"), gsscd_memorized=("gsscd_memorized", "mean"),
        ofs_mean=(ofs, "mean"), ofs_median=(ofs, "median"), ofs_memorized=(f"{ofs}_memorized", "mean"),
        ofs_nmf_videos=(f"{ofs}_nmf", "count"), ofs_nmf_mean=(f"{ofs}_nmf", "mean"),
        ofs_nmf_median=(f"{ofs}_nmf", "median"), ofs_nmf_memorized=(f"{ofs}_nmf_memorized", "mean"))


# The experiments of `main.py batch`: the plain videos (normal) and the five mitigation methods. Each one's videos are
# in <out>/<experiment>/, all made from the same captions and the same starting noise (seed).
EXPERIMENTS = {"normal": "No mitigation", "guard": "GUARD", "soften": "Softened attention", "clip": "CLIP embeddings",
               "noise": "Initial-noise adjustment", "sail": "SAIL"}


def result_file(folder, name, experiment="normal"):
    """The plain videos keep the names of the first evaluation (metrics.csv, ...); a mitigation adds its name
    (metrics_guard.csv, ...)."""
    stem, extension = os.path.splitext(name)
    return os.path.join(folder, name if experiment == "normal" else f"{stem}_{experiment}{extension}")


def experiment_list(text):
    experiments = text.split(",")
    unknown = set(experiments) - set(EXPERIMENTS)
    if unknown:
        raise SystemExit(f"unknown experiment {', '.join(sorted(unknown))}: use any of {','.join(EXPERIMENTS)}")
    return experiments


def run_metrics(args):
    """GSSCD and OFS-k of every generated video against its training clip, for each experiment -> metrics.csv,
    summary_role.csv and summary_copies.csv in --out (with the experiment's name added, except for normal)."""
    if not 1 <= args.k <= 15:
        raise SystemExit("--k must be between 1 and 15: 16 frames have 15 flows")
    experiments = experiment_list(args.experiments)
    if args.videos and len(experiments) > 1:
        raise SystemExit("--videos works with one experiment only; without it, <out>/<experiment>/ is used")
    sheet = pd.read_csv(os.path.join(args.out, "prompts.csv"), keep_default_na=False).rename(columns={"index": "videoid"})
    folder = lambda experiment: args.videos or os.path.join(args.out, experiment)
    gif = lambda experiment, v: os.path.join(folder(experiment), f"{v}.gif")
    for experiment in experiments:  # averages over part of the videos could not be compared
        missing = [v for v in sheet["videoid"] if not os.path.exists(gif(experiment, v))]
        if missing:
            raise SystemExit(f"{experiment}: {len(missing)} of {len(sheet)} videos are not generated yet in {folder(experiment)}")

    sscd = load_sscd(args.sscd_weights if os.path.exists(args.sscd_weights) else None)
    raft = raft_large(weights=Raft_Large_Weights.DEFAULT).cuda().eval()

    ofs = f"ofs_{args.k}"
    rows = {experiment: [] for experiment in experiments}
    for row in tqdm(sheet.itertuples(), total=len(sheet), desc="metrics"):
        # The training clip is the same for every experiment: its SSCD embeddings and flows are computed once.
        training = read_clip(video_path(args, row.videoid))
        t = embed(sscd, square(training, SSCD_SIZE, crop=True)).float()
        ft = optical_flow(raft, square(training, FLOW_SIZE, crop=True))
        ignored_training = natural_motion(ft, args.min_magnitude, args.min_entropy)

        for experiment in experiments:
            generated = gif_frames(gif(experiment, row.videoid))

            # GSSCD (Eq. 2): the largest SSCD cosine similarity over all the pairs of frames.
            g = embed(sscd, square(generated, SSCD_SIZE, crop=False)).float()
            gsscd = (g @ t.T).max().item()

            # OFS-k, without and with the natural motion filter (the paper reports both).
            fg = optical_flow(raft, square(generated, FLOW_SIZE, crop=False))
            S = flow_similarity(fg, ft)
            filtered = ofs_k(S, args.k, natural_motion(fg, args.min_magnitude, args.min_entropy), ignored_training)

            rows[experiment].append({"videoid": row.videoid, "role": row.role, "copies": row.copies,
                                     "caption": row.caption, "gsscd": gsscd, ofs: ofs_k(S, args.k), f"{ofs}_nmf": filtered})

    for experiment in experiments:
        df = pd.DataFrame(rows[experiment])
        df["gsscd_memorized"] = df["gsscd"] >= args.gsscd_threshold
        df[f"{ofs}_memorized"] = df[ofs] > args.ofs_threshold
        df[f"{ofs}_nmf_memorized"] = df[f"{ofs}_nmf"] > args.ofs_threshold  # a video with no window left counts as False

        files = [result_file(args.out, name, experiment) for name in ["metrics.csv", "summary_role.csv", "summary_copies.csv"]]
        df.to_csv(files[0], index=False, float_format="%.4f")
        by_role = summarize(df, "role", ofs)
        by_copies = summarize(df[df["role"] == "memorized"], "copies", ofs)  # does memorization grow with the copies?
        by_role.to_csv(files[1], float_format="%.4f")
        by_copies.to_csv(files[2], float_format="%.4f")
        with pd.option_context("display.width", 250, "display.max_columns", None):
            print(f"\n{EXPERIMENTS[experiment]}\n{by_role.round(3)}")
        print(f"-> {', '.join(files)}")


# ------------------------------------------------------------------------------------------------------------------
# Part 3: the figures
# ------------------------------------------------------------------------------------------------------------------

MEMORIZED_COLOR, BACKGROUND_COLOR = "#2a78d6", "#eb6834"
INK, MUTED, GRID = "#0b0b0b", "#52514e", "#e6e5e0"


def metric_panels(df, args):
    """What each panel of a figure shows: (column, title, threshold, share of videos counted as memorized per row)."""
    ofs = next(c for c in df.columns if re.fullmatch(r"ofs_\d+", c))
    k = ofs.split("_")[1]
    return [("gsscd", "GSSCD (content)", args.gsscd_threshold, df["gsscd"] >= args.gsscd_threshold),
            (ofs, f"OFS-{k} (motion)", args.ofs_threshold, df[ofs] > args.ofs_threshold),
            (f"{ofs}_nmf", f"OFS-{k} with natural motion filter", args.ofs_threshold, df[f"{ofs}_nmf"] > args.ofs_threshold)]


def legend_below(fig, ax):
    """One legend for all the panels, below them, so that it cannot cover the data."""
    handles, labels = ax.get_legend_handles_labels()
    fig.legend(handles, labels, frameon=False, ncol=len(labels), loc="lower center", fontsize=11)
    fig.tight_layout(rect=(0, 0.09, 1, 1))


def plot_distributions(df, panels, plt):
    """How the scores of the memorized and the background videos are spread."""
    fig, axes = plt.subplots(1, 3, figsize=(14, 4.4), sharey=False)
    bins = np.arange(-1, 1.0001, 0.05)
    for ax, (column, title, threshold, _) in zip(axes, panels):
        for role, color, label in [("memorized", MEMORIZED_COLOR, "Memorized"), ("background", BACKGROUND_COLOR, "Background")]:
            values = df.loc[df["role"] == role, column].dropna()
            ax.hist(values, bins=bins, histtype="step", linewidth=2, color=color, label=label)
            ax.hist(values, bins=bins, color=color, alpha=0.15)
        ax.axvline(threshold, color=MUTED, linestyle="--", linewidth=1.2, label="Threshold of the paper")
        ax.text(threshold, 0.99, f" {threshold:g}", transform=ax.get_xaxis_transform(), va="top", color=MUTED)
        ax.set_title(title, loc="left")
        counts = df.dropna(subset=[column])["role"].value_counts()
        ax.set_xlabel(f"Score (n = {counts['memorized']} memorized, {counts['background']} background)")
        ax.set_xlim(max(-1, df[column].min() - 0.05), 1)
    axes[0].set_ylabel("Videos")
    legend_below(fig, axes[0])
    return fig


def plot_copies(df, panels, plt):
    """Does the score grow with the number of copies? Every memorized video, the trend, and the background as reference."""
    memorized, background = df[df["role"] == "memorized"], df[df["role"] == "background"]
    levels = np.sort(memorized["copies"].unique())
    fig, axes = plt.subplots(1, 3, figsize=(14, 4.4), sharex=True)
    for ax, (column, title, threshold, _) in zip(axes, panels):
        # The trend: the mean of 5 neighbouring numbers of copies (a single level has only a few videos).
        trend = memorized.groupby("copies")[column].mean().reindex(levels).rolling(5, center=True, min_periods=1).mean()
        ax.scatter(memorized["copies"], memorized[column], s=22, color=MEMORIZED_COLOR, alpha=0.35, linewidths=0, label="One memorized video")
        ax.plot(levels, trend, color=MEMORIZED_COLOR, linewidth=2.5, label="Trend (mean over 5 levels)")
        ax.axhline(background[column].median(), color=BACKGROUND_COLOR, linewidth=2, label="Background median")
        ax.axhline(threshold, color=MUTED, linestyle="--", linewidth=1.2, label="Threshold of the paper")
        ax.text(0.995, threshold, f"{threshold:g}", transform=ax.get_yaxis_transform(), ha="right", va="bottom", color=MUTED,
                bbox=dict(facecolor="white", edgecolor="none", alpha=0.8, pad=1))
        ax.set_title(title, loc="left")
        ax.set_xlabel("Copies in the fine-tuning dataset")
        ax.set_ylim(min(-0.1, memorized[column].min() - 0.05), 1.05)
    axes[0].set_ylabel("Score")
    legend_below(fig, axes[0])
    return fig


def plot_share(df, panels, groups, plt):
    """The share of videos counted as memorized: the background, then the memorized videos grouped by their copies."""
    levels = np.array_split(np.sort(df.loc[df["role"] == "memorized", "copies"].unique()), groups)
    masks = [df["role"] == "background"] + [(df["role"] == "memorized") & df["copies"].isin(l) for l in levels]
    names = ["Background\n(1 copy)"] + [f"{l[0]}–{l[-1]}" for l in levels]
    colors = [BACKGROUND_COLOR] + [MEMORIZED_COLOR] * len(levels)
    fig, axes = plt.subplots(1, 3, figsize=(14, 4.4), sharey=True)
    for ax, (_, title, _, is_memorized) in zip(axes, panels):
        shares = [100 * is_memorized[m].mean() for m in masks]
        bars = ax.bar(names, shares, color=colors, width=0.72)
        ax.bar_label(bars, labels=[f"{s:.0f}%" for s in shares], padding=3, fontsize=11, color=INK)
        ax.set_title(title, loc="left")
        ax.set_xlabel("Copies in the fine-tuning dataset")
        ax.tick_params(axis="x", labelsize=10)
        ax.grid(False, axis="x")
    axes[0].set_ylabel("Videos counted as memorized (%)")
    axes[0].set_ylim(0, 112)
    fig.tight_layout(rect=(0, 0.05, 1, 1))
    fig.text(0.5, 0.01, "Share of all the videos of each group. With the filter, a video with no window left counts as not memorized.",
             ha="center", fontsize=11, color=MUTED)
    return fig


def plot_content_vs_motion(df, panels, plt):
    """Content and motion together: every video, with the counts in the four areas the two thresholds make."""
    (x, _, x_threshold, x_memorized), (y, _, y_threshold, y_memorized) = panels[:2]
    fig, ax = plt.subplots(figsize=(8, 6.2))
    for role, color, label in [("background", BACKGROUND_COLOR, "Background"), ("memorized", MEMORIZED_COLOR, "Memorized")]:
        rows = df["role"] == role
        ax.scatter(df.loc[rows, x], df.loc[rows, y], s=42, color=color, edgecolors="white", linewidths=0.8, label=label)
    ax.axvline(x_threshold, color=MUTED, linestyle="--", linewidth=1.2)
    ax.axhline(y_threshold, color=MUTED, linestyle="--", linewidth=1.2)
    ax.set_xlabel(panels[0][1])
    ax.set_ylabel(panels[1][1])
    ax.set_xlim(min(-0.08, df[x].min() - 0.03), 1)
    ax.set_ylim(min(-0.1, df[y].min() - 0.32), 1.2)  # room for the labels of the two lower areas
    # One label per area: how many memorized (M) and background (B) videos fall into it.
    bottom = ax.get_ylim()[0] + 0.02
    corners = [(False, True, ax.get_xlim()[0] + 0.015, 1.17, "left", "top", "Motion only"),
               (True, True, 0.985, 1.17, "right", "top", "Content and motion"),
               (False, False, ax.get_xlim()[0] + 0.015, bottom, "left", "bottom", "Neither"),
               (True, False, 0.985, bottom, "right", "bottom", "Content only")]
    for content, motion, tx, ty, ha, va, name in corners:
        rows = (x_memorized == content) & (y_memorized == motion)
        ax.text(tx, ty, f"{name}\nM {(rows & (df['role'] == 'memorized')).sum()}  ·  B {(rows & (df['role'] == 'background')).sum()}",
                ha=ha, va=va, fontsize=11, color=INK, bbox=dict(facecolor="white", edgecolor="none", alpha=0.85, pad=2))
    ax.legend(frameon=False, loc="center left", bbox_to_anchor=(1.0, 0.5))
    fig.tight_layout()
    return fig


def pyplot():
    """matplotlib without a screen, in the style of all the figures."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    plt.rcParams.update({"font.size": 12, "axes.titlesize": 14, "text.color": INK, "axes.labelcolor": MUTED,
                         "xtick.color": MUTED, "ytick.color": MUTED, "axes.edgecolor": GRID, "axes.spines.top": False,
                         "axes.spines.right": False, "axes.grid": True, "grid.color": GRID, "grid.linewidth": 0.8,
                         "axes.axisbelow": True, "figure.facecolor": "white", "pdf.fonttype": 42})
    return plt


def read_metrics(folder, experiment="normal"):
    path = result_file(folder, "metrics.csv", experiment)
    if not os.path.exists(path):
        raise SystemExit(f"{path} is missing: run `memorization_eval.py --out {folder} metrics --experiments {experiment}` first")
    return pd.read_csv(path, keep_default_na=False, na_values=[""])


def save_figures(figures, folder, title, plt):
    """Every figure as PNG (slides) and PDF (papers). title: written above each figure, if given."""
    os.makedirs(folder, exist_ok=True)
    for name, fig in figures.items():
        if title:  # above the panels; bbox_inches="tight" makes room for it
            fig.suptitle(title, x=0.01, y=1.0, ha="left", va="bottom", fontsize=15, fontweight="bold")
        for extension, dpi in [("png", 200), ("pdf", None)]:
            fig.savefig(os.path.join(folder, f"{name}.{extension}"), dpi=dpi, bbox_inches="tight")
        plt.close(fig)
    print(f"-> {folder}: {', '.join(figures)} (.png and .pdf)")


def run_plot(args):
    """Figures of one experiment's metrics for presenting, in <--out>/plots (normal) or <--out>/plots_<experiment>."""
    plt = pyplot()
    df = read_metrics(args.out, args.experiment)
    panels = metric_panels(df, args)
    figures = {"distributions": plot_distributions(df, panels, plt), "score_vs_copies": plot_copies(df, panels, plt),
               "share_memorized": plot_share(df, panels, args.groups, plt), "content_vs_motion": plot_content_vs_motion(df, panels, plt)}
    title = args.title or (None if args.experiment == "normal" else f"Fine-tuned model with {EXPERIMENTS[args.experiment]}")
    folder = os.path.join(args.out, "plots" if args.experiment == "normal" else f"plots_{args.experiment}")
    save_figures(figures, folder, title, plt)


def threshold_panels(df, args):
    """metric_panels, with a test that takes any column of scores instead of the mask of one table."""
    return [(column, title, threshold, (lambda v, t=threshold, c=column: v >= t if c == "gsscd" else v > t))
            for column, title, threshold, _ in metric_panels(df, args)]


# ------------------------------------------------------------------------------------------------------------------
# Part 4: the fine-tuned model against the original model
# ------------------------------------------------------------------------------------------------------------------
# Both models generate a video from the same caption and the same starting noise (seed), and both videos are compared
# with the same training clip. So each video of the fine-tuned model has a twin from the original model, and the
# difference between the twins is the effect of the fine-tuning. Gray is the original model; the fine-tuned model keeps
# the colors of the other figures (blue: memorized samples, orange: background samples).

ORIGINAL_COLOR = "#9b9a94"
MODELS = [("original", "Original model"), ("finetuned", "Fine-tuned model")]


def paired_metrics(args):
    """One row per video, with the scores of both models: <column>_original and <column>_finetuned."""
    original, finetuned = read_metrics(args.original), read_metrics(args.finetuned)
    if set(original["videoid"]) != set(finetuned["videoid"]):
        raise SystemExit("the two folders have different videos: generate both from the same prompts.csv")
    scores = [c for c in finetuned.columns if c == "gsscd" or re.fullmatch(r"ofs_\d+(_nmf)?", c)]
    return finetuned[["videoid", "role", "copies", "caption"]].merge(
        original[["videoid"] + scores].merge(finetuned[["videoid"] + scores], on="videoid", suffixes=("_original", "_finetuned")),
        on="videoid")


def groups_of(df, groups):
    """(name, rows): the background, all the memorized samples, then the memorized samples grouped by their copies."""
    levels = np.array_split(np.sort(df.loc[df["role"] == "memorized", "copies"].unique()), groups)
    return ([("Background\n(1 copy)", df["role"] == "background"), ("All\nmemorized", df["role"] == "memorized")] +
            [(f"{l[0]}–{l[-1]}", (df["role"] == "memorized") & df["copies"].isin(l)) for l in levels])


def plot_compare_share(df, panels, groups, plt):
    """The share of videos counted as memorized, original (gray) against fine-tuned (colored), for every group."""
    named = [g for g in groups_of(df, groups) if not g[0].startswith("All")]  # the groups already add up to all
    x = np.arange(len(named))
    fig, axes = plt.subplots(1, 3, figsize=(15, 4.6), sharey=True)
    for ax, (column, title, threshold, above) in zip(axes, panels):
        for offset, (model, label) in zip([-0.19, 0.19], MODELS):
            values = df[f"{column}_{model}"]
            shares = [100 * above(values[rows]).mean() for _, rows in named]
            colors = ([ORIGINAL_COLOR] * len(named) if model == "original"
                      else [BACKGROUND_COLOR] + [MEMORIZED_COLOR] * (len(named) - 1))
            bars = ax.bar(x + offset, shares, width=0.36, color=colors, label=label)
            ax.bar_label(bars, labels=[f"{s:.0f}" for s in shares], padding=2, fontsize=9, color=INK)
        ax.set_xticks(x, [name for name, _ in named], fontsize=10)
        ax.set_title(title, loc="left")
        ax.set_xlabel("Copies in the fine-tuning dataset")
        ax.grid(False, axis="x")
    axes[0].set_ylabel("Videos counted as memorized (%)")
    axes[0].set_ylim(0, 112)
    fig.tight_layout(rect=(0, 0.06, 1, 1))
    fig.text(0.5, 0.01, "Left bar of each pair (gray): original model.   Right bar (colored): fine-tuned model.   "
             "Numbers are % of the videos of the group.", ha="center", fontsize=11, color=MUTED)
    return fig


def plot_compare_copies(df, panels, plt):
    """The mean score against the copies, for both models. The background is drawn at 1 copy, as a diamond."""
    memorized, background = df[df["role"] == "memorized"], df[df["role"] == "background"]
    levels = np.sort(memorized["copies"].unique())
    fig, axes = plt.subplots(1, 3, figsize=(15, 4.6), sharex=True)
    for ax, (column, title, threshold, _) in zip(axes, panels):
        lowest = -0.05
        for model, label in MODELS:
            line_color = ORIGINAL_COLOR if model == "original" else MEMORIZED_COLOR
            dot_color = ORIGINAL_COLOR if model == "original" else BACKGROUND_COLOR
            values = f"{column}_{model}"
            # The mean of 5 neighbouring numbers of copies, as in score_vs_copies (a single level has only 4 videos).
            trend = memorized.groupby("copies")[values].mean().reindex(levels).rolling(5, center=True, min_periods=1).mean()
            # Gaps: no video of these copies has a score (with the filter, a video can have no window left).
            ax.plot(levels, trend, color=line_color, linewidth=2.5, label=f"{label}: memorized samples")
            lowest = min(lowest, trend.min() - 0.05)
            ax.scatter([1], [background[values].mean()], marker="D", s=70, color=dot_color, edgecolors="white",
                       linewidths=1, zorder=3, label=f"{label}: background (1 copy)")
        ax.axhline(threshold, color=MUTED, linestyle="--", linewidth=1.2, label="Threshold of the paper")
        ax.set_title(title, loc="left")
        ax.set_xlabel("Copies in the fine-tuning dataset")
        ax.set_ylim(lowest, 1.05)
    axes[0].set_ylabel("Mean score")
    handles, labels = axes[0].get_legend_handles_labels()
    fig.legend(handles, labels, frameon=False, ncol=3, loc="lower center", fontsize=11)
    fig.tight_layout(rect=(0, 0.14, 1, 1))
    return fig


def plot_compare_paired(df, panels, plt):
    """Every video against its twin: original score (x) and fine-tuned score (y). Above the diagonal = the fine-tuning
    made the video closer to its training clip."""
    fig, axes = plt.subplots(1, 3, figsize=(15, 5.2))
    for ax, (column, title, threshold, _) in zip(axes, panels):
        both = df.dropna(subset=[f"{column}_original", f"{column}_finetuned"])  # the filter can leave no window
        low = min(-0.1, both[[f"{column}_original", f"{column}_finetuned"]].min().min() - 0.05)
        ax.plot([low, 1.03], [low, 1.03], color=MUTED, linewidth=1.2, label="No change")
        ax.axvline(threshold, color=MUTED, linestyle="--", linewidth=1.2)
        ax.axhline(threshold, color=MUTED, linestyle="--", linewidth=1.2, label="Threshold of the paper")
        counts = []
        for role, color, label in [("background", BACKGROUND_COLOR, "Background"), ("memorized", MEMORIZED_COLOR, "Memorized")]:
            rows = both[both["role"] == role]
            ax.scatter(rows[f"{column}_original"], rows[f"{column}_finetuned"], s=30, color=color, edgecolors="white",
                       linewidths=0.6, label=label)
            up = (rows[f"{column}_finetuned"] > rows[f"{column}_original"]).sum()
            counts.append(f"{label} {up}/{len(rows)}")
        ax.set_xlim(low, 1.03)
        ax.set_ylim(low, 1.03)
        ax.set_aspect("equal")
        ax.set_title(title, loc="left")
        # How many videos lie above the diagonal (only videos with a score from both models are drawn and counted).
        ax.set_xlabel(f"Original model\nHigher after fine-tuning:\n{counts[1]} · {counts[0]}")
    axes[0].set_ylabel("Fine-tuned model")
    legend_below(fig, axes[0])
    return fig


def plot_compare_distributions(df, panels, plt):
    """How the scores are spread, original (gray) against fine-tuned (colored): memorized samples on top, background below."""
    fig, axes = plt.subplots(2, 3, figsize=(15, 7.6), sharex="col")
    bins = np.arange(-1, 1.0001, 0.05)
    for r, (role, color, name) in enumerate([("memorized", MEMORIZED_COLOR, "Memorized samples"),
                                             ("background", BACKGROUND_COLOR, "Background samples")]):
        for ax, (column, title, threshold, _) in zip(axes[r], panels):
            rows = df[df["role"] == role]
            n = []
            for model, label in MODELS:
                c = ORIGINAL_COLOR if model == "original" else color
                values = rows[f"{column}_{model}"].dropna()
                ax.hist(values, bins=bins, histtype="step", linewidth=2, color=c,
                        label=label if model == "original" else f"{label}, {role} samples")
                ax.hist(values, bins=bins, color=c, alpha=0.15)
                n.append(len(values))
            ax.axvline(threshold, color=MUTED, linestyle="--", linewidth=1.2, label="Threshold of the paper")
            ax.set_title(f"{name} · {title}", loc="left", fontsize=12.5)
            ax.set_xlim(max(-1, df[[f"{column}_original", f"{column}_finetuned"]].min().min() - 0.05), 1)
            ax.set_xlabel(f"Score (n = {n[0]} original, {n[1]} fine-tuned)", fontsize=11)
        axes[r][0].set_ylabel("Videos")
    # One legend below: gray, blue, orange, the threshold.
    handles, labels = axes[0][0].get_legend_handles_labels()
    more, more_labels = axes[1][0].get_legend_handles_labels()
    order = [(handles[0], labels[0]), (handles[1], labels[1]), (more[1], more_labels[1]), (handles[2], labels[2])]
    fig.legend(*zip(*order), frameon=False, ncol=4, loc="lower center", fontsize=11)
    fig.tight_layout(rect=(0, 0.05, 1, 1))
    return fig


def compare_summary(df, panels, groups):
    """Per group and metric: both models' mean and share of memorized videos, the mean change, and whether the change
    is larger than chance (Wilcoxon signed-rank test on the twins)."""
    from scipy.stats import wilcoxon
    rows = []
    for name, members in groups_of(df, groups):
        for column, title, _, above in panels:
            pair = df.loc[members, [f"{column}_original", f"{column}_finetuned"]].dropna()
            o, f = pair[f"{column}_original"], pair[f"{column}_finetuned"]
            rows.append({"group": name.replace("\n", " "), "metric": column, "videos": len(pair),
                         "original_mean": o.mean(), "finetuned_mean": f.mean(), "mean_change": (f - o).mean(),
                         "original_memorized_%": 100 * above(o).mean(), "finetuned_memorized_%": 100 * above(f).mean(),
                         "higher_after_finetuning": int((f > o).sum()),
                         "wilcoxon_p": wilcoxon(f, o).pvalue if len(pair) >= 6 else np.nan})
    return pd.DataFrame(rows)


def run_compare(args):
    """Figures and a table of the fine-tuned model against the original model, in --save-to."""
    plt = pyplot()
    df = paired_metrics(args)
    panels = threshold_panels(read_metrics(args.finetuned), args)  # the test takes the scores of either model
    os.makedirs(args.save_to, exist_ok=True)
    df.to_csv(os.path.join(args.save_to, "paired_metrics.csv"), index=False, float_format="%.4f")
    summary = compare_summary(df, panels, args.groups)
    summary.to_csv(os.path.join(args.save_to, "compare_summary.csv"), index=False, float_format="%.4g")
    with pd.option_context("display.width", 250, "display.max_columns", None, "display.max_rows", None):
        print(summary.round(3).to_string(index=False))
    figures = {"compare_share_memorized": plot_compare_share(df, panels, args.groups, plt),
               "compare_score_vs_copies": plot_compare_copies(df, panels, plt),
               "compare_paired": plot_compare_paired(df, panels, plt),
               "compare_distributions": plot_compare_distributions(df, panels, plt)}
    save_figures(figures, args.save_to, None, plt)
    print(f"-> {args.save_to}: paired_metrics.csv, compare_summary.csv")


# ------------------------------------------------------------------------------------------------------------------
# Part 5: the mitigation methods on the fine-tuned model
# ------------------------------------------------------------------------------------------------------------------
# A method works if the memorized samples are copied less than without mitigation (normal), ideally as little as by the
# original model, which never saw the duplicates. Every method generates each caption from the same starting noise as
# normal, so each video is compared with its own twin without mitigation.

NO_MITIGATION_COLOR = "#52514e"


def mitigation_scores(args):
    """{name: metrics table}, all in the order of the videos of normal: the experiments, then "original" if found."""
    tables = {experiment: read_metrics(args.out, experiment) for experiment in experiment_list(args.experiments)}
    if "normal" not in tables:
        raise SystemExit("--experiments must include normal: the methods are compared with it")
    if args.original and os.path.exists(os.path.join(args.original, "metrics.csv")):
        tables["original"] = read_metrics(args.original)
    order = tables["normal"]["videoid"]
    for name, table in tables.items():
        if set(table["videoid"]) != set(order):
            raise SystemExit(f"{name} has other videos than normal: generate every experiment from the same prompts.csv")
        tables[name] = table.set_index("videoid").loc[order].reset_index()
    return tables


def label_of(name):
    """Name under a bar, on two lines if it is long."""
    return "Original model\n(reference)" if name == "original" else EXPERIMENTS[name].replace(" ", "\n", 1)


def mitigation_summary(tables, panels, groups):
    """Per method, group and metric: the mean, the share of videos counted as memorized, the change against normal
    (mean change of the twins, Wilcoxon signed-rank p-value), and how many of the videos memorized without mitigation
    are still memorized with the method."""
    from scipy.stats import wilcoxon
    normal, rows = tables["normal"], []
    for name, table in tables.items():
        for group, members in groups_of(normal, groups):
            for column, _, _, above in panels:
                values, before = table.loc[members, column], normal.loc[members, column]
                pair = pd.DataFrame({"before": before, "after": values}).dropna()
                change = pair["after"] - pair["before"]
                was = above(before)
                rows.append({"method": name, "group": group.replace("\n", " "), "metric": column,
                             "videos_with_score": int(values.notna().sum()), "mean": values.mean(),
                             "memorized_%": 100 * above(values).mean(),
                             "mean_change_vs_normal": change.mean() if name != "normal" else np.nan,
                             "wilcoxon_p_vs_normal": (wilcoxon(pair["after"], pair["before"]).pvalue
                                                      if name != "normal" and len(pair) >= 6 and change.any() else np.nan),
                             "memorized_without_mitigation": int(was.sum()),
                             "still_memorized": int((was & above(values)).sum())})
    return pd.DataFrame(rows)


def plot_mitigation_share(tables, panels, plt):
    """The share of videos counted as memorized for every method: memorized samples (blue) and background (orange)."""
    names = list(tables)
    x = np.arange(len(names))
    roles = tables["normal"]["role"]
    fig, axes = plt.subplots(len(panels), 1, figsize=(max(9, 1.6 * len(names)), 4.1 * len(panels)), sharex=True)
    for ax, (column, title, _, above) in zip(axes, panels):
        for offset, role, color, label in [(-0.19, "memorized", MEMORIZED_COLOR, "Memorized samples (2–51 copies)"),
                                           (0.19, "background", BACKGROUND_COLOR, "Background samples (1 copy)")]:
            shares = [100 * above(tables[n][column])[roles == role].mean() for n in names]
            bars = ax.bar(x + offset, shares, width=0.36, color=color, label=label)
            ax.bar_label(bars, labels=[f"{s:.0f}%" for s in shares], padding=2, fontsize=10, color=INK)
        if "original" in tables:  # the reference is not a method: set it apart
            ax.axvline(len(names) - 1.5, color=GRID, linewidth=1.5)
        ax.set_title(title, loc="left")
        ax.set_ylabel("Counted as memorized (%)")
        ax.set_ylim(0, 112)
        ax.grid(False, axis="x")
    axes[-1].set_xticks(x, [label_of(n) for n in names], fontsize=11)
    legend_below(fig, axes[0])
    fig.tight_layout(rect=(0, 0.04, 1, 1))
    return fig


def plot_mitigation_copies(tables, panels, plt):
    """One panel per method and metric: the mean score against the copies, for the method (blue), no mitigation (dark
    gray) and the original model (light gray). Below no mitigation = the method lowers the copying."""
    methods = [n for n in tables if n not in ("normal", "original")]
    panels = panels[:2]  # with the filter, too few videos have a score for a trend per number of copies
    memorized = tables["normal"]["role"] == "memorized"
    copies = tables["normal"]["copies"][memorized]
    levels = np.sort(copies.unique())
    fig, axes = plt.subplots(len(panels), len(methods), figsize=(3.6 * len(methods) + 1, 3.9 * len(panels)),
                             sharex=True, sharey="row", squeeze=False)
    lines = [("original", ORIGINAL_COLOR, "Original model (never saw the duplicates)"),
             ("normal", NO_MITIGATION_COLOR, "Fine-tuned, no mitigation")]
    for c, method in enumerate(methods):
        for r, (column, title, threshold, _) in enumerate(panels):
            ax = axes[r][c]
            for name, color, label in lines + [(method, MEMORIZED_COLOR, "Fine-tuned, with the method of the panel")]:
                if name not in tables:
                    continue
                # The mean of 5 neighbouring numbers of copies, as in score_vs_copies.
                trend = (tables[name][column][memorized].groupby(copies).mean().reindex(levels)
                         .rolling(5, center=True, min_periods=1).mean())
                ax.plot(levels, trend, color=color, linewidth=2.5 if name == method else 2, label=label)
            ax.axhline(threshold, color=MUTED, linestyle="--", linewidth=1.2, label="Threshold of the paper")
            ax.set_title(f"{EXPERIMENTS[method]} · {title.split(' (')[0]}", loc="left", fontsize=12.5)
            if r == len(panels) - 1:
                ax.set_xlabel("Copies in the fine-tuning dataset")
        for r, (_, title, _, _) in enumerate(panels):
            axes[r][0].set_ylabel(f"Mean {title.split(' (')[0]}")
    legend_below(fig, axes[0][0])
    fig.tight_layout(rect=(0, 0.08, 1, 1))
    return fig


def run_mitigation(args):
    """Figures and a table of every mitigation method against no mitigation (and the original model), in --save-to."""
    plt = pyplot()
    tables = mitigation_scores(args)
    panels = threshold_panels(tables["normal"], args)
    os.makedirs(args.save_to, exist_ok=True)
    summary = mitigation_summary(tables, panels, args.groups)
    summary.to_csv(os.path.join(args.save_to, "mitigation_summary.csv"), index=False, float_format="%.4g")
    main_rows = summary[summary["group"].isin(["Background (1 copy)", "All memorized"])]
    with pd.option_context("display.width", 250, "display.max_columns", None, "display.max_rows", None):
        print(main_rows.round(3).to_string(index=False))
    figures = {"mitigation_share_memorized": plot_mitigation_share(tables, panels, plt)}
    if len([n for n in tables if n not in ("normal", "original")]):
        figures["mitigation_score_vs_copies"] = plot_mitigation_copies(tables, panels, plt)
    save_figures(figures, args.save_to, None, plt)
    print(f"-> {args.save_to}: mitigation_summary.csv")


def main():
    parser = argparse.ArgumentParser(description="GSSCD and OFS-k of videos generated by the fine-tuned model")
    parser.add_argument("--root", default="data/webvid", help="the WebVid folder of webvid.py (where the videos are)")
    parser.add_argument("--out", default="outputs/finetune_eval", help="folder of the sheet and the results")
    sub = parser.add_subparsers(dest="command", required=True)

    p = sub.add_parser("prompts", help="write the sheet: the memorized samples and as many random background samples")
    p.add_argument("--table", default="outputs/finetune/finetune.csv", help="the table the model was fine-tuned on")
    p.add_argument("--seed", type=int, default=0, help="which background samples are drawn")

    m = sub.add_parser("metrics", help="GSSCD and OFS-k of the generated videos")
    m.add_argument("--experiments", default="normal",
                   help=f"experiments of `main.py batch` to measure, any of {','.join(EXPERIMENTS)}; videos in <out>/<experiment>/")
    m.add_argument("--videos", default=None, help="another folder of the generated <videoid>.gif (one experiment only)")
    m.add_argument("--k", type=int, default=3, help="flows per window of OFS-k (the paper's best: 3)")
    m.add_argument("--gsscd-threshold", type=float, default=0.4, help="GSSCD from which content is memorized (paper: 0.4)")
    m.add_argument("--ofs-threshold", type=float, default=0.5, help="OFS-k above which motion is memorized (paper: 0.5)")
    m.add_argument("--min-magnitude", type=float, default=0.5,
                   help="natural motion filter: mean flow length in pixels below which a flow is static (not in the paper)")
    m.add_argument("--min-entropy", type=float, default=0.5,
                   help="natural motion filter: direction entropy, 0 to 1, below which a flow is panning (not in the paper)")
    m.add_argument("--sscd-weights", default="data/webvid/models/sscd_disc_mixup.classy.pt",
                   help="SSCD weights; downloaded if missing")

    f = sub.add_parser("plot", help="figures of metrics.csv, in <--out>/plots")
    f.add_argument("--gsscd-threshold", type=float, default=0.4, help="line in the figures, and what counts as memorized")
    f.add_argument("--ofs-threshold", type=float, default=0.5, help="line in the figures, and what counts as memorized")
    f.add_argument("--groups", type=int, default=5, help="groups of copies in share_memorized")
    f.add_argument("--title", default=None, help='written above every figure, e.g. "Fine-tuned model"')
    f.add_argument("--experiment", default="normal", choices=list(EXPERIMENTS),
                   help="whose metrics to draw; figures in <out>/plots (normal) or <out>/plots_<experiment>")

    c = sub.add_parser("compare", help="figures of the fine-tuned model against the original model, same prompts")
    c.add_argument("--finetuned", default="outputs/finetune_eval", help="folder with metrics.csv of the fine-tuned model")
    c.add_argument("--original", default="outputs/finetune_eval_original", help="folder with metrics.csv of the original model")
    c.add_argument("--save-to", default="outputs/finetune_compare", help="folder of the figures and tables")
    c.add_argument("--gsscd-threshold", type=float, default=0.4, help="line in the figures, and what counts as memorized")
    c.add_argument("--ofs-threshold", type=float, default=0.5, help="line in the figures, and what counts as memorized")
    c.add_argument("--groups", type=int, default=5, help="groups of copies")

    g = sub.add_parser("mitigation", help="figures of the mitigation methods against no mitigation, same prompts")
    g.add_argument("--experiments", default=",".join(EXPERIMENTS),
                   help="experiments to compare (metrics in --out), normal included")
    g.add_argument("--original", default="outputs/finetune_eval_original",
                   help="folder with metrics.csv of the original model, drawn as the reference if it exists ('' = none)")
    g.add_argument("--save-to", default="outputs/finetune_mitigation", help="folder of the figures and the table")
    g.add_argument("--gsscd-threshold", type=float, default=0.4, help="line in the figures, and what counts as memorized")
    g.add_argument("--ofs-threshold", type=float, default=0.5, help="line in the figures, and what counts as memorized")
    g.add_argument("--groups", type=int, default=5, help="groups of copies in the table")

    args = parser.parse_args()
    {"prompts": run_prompts, "metrics": run_metrics, "plot": run_plot, "compare": run_compare,
     "mitigation": run_mitigation}[args.command](args)


if __name__ == "__main__":
    main()
